"""通过模拟 LLM 验证反思流程，不调用真实模型服务。"""

import io
import unittest
from contextlib import redirect_stdout
from unittest.mock import Mock

from hello_agents import HelloAgentsLLM, ReflectionAgent
from my_reflection_agent import DEFAULT_PROMPTS, MyReflectionAgent


class MyReflectionAgentTests(unittest.TestCase):
    """验证框架集成、提示词配置与迭代边界。"""

    def setUp(self):
        """隐藏流程日志，让测试结果只显示断言状态。"""
        self.enterContext(redirect_stdout(io.StringIO()))

    def make_agent(self, responses, **kwargs):
        """为每个用例创建独立的模拟 LLM 和反思 Agent。"""
        llm = Mock(spec=HelloAgentsLLM)
        llm.invoke.side_effect = responses
        return MyReflectionAgent(name="测试反思助手", llm=llm, **kwargs), llm

    def test_stops_when_feedback_needs_no_improvement(self):
        """中英文完成反馈都应直接返回初稿，并保存最终对话。"""
        for feedback in ("无需改进", "No Need For Improvement"):
            with self.subTest(feedback=feedback):
                agent, llm = self.make_agent(["初稿", feedback])
                self.assertIsInstance(agent, ReflectionAgent)
                self.assertEqual(agent.run("写文章"), "初稿")
                self.assertEqual(llm.invoke.call_count, 2)
                self.assertEqual(
                    [(m.role, m.content) for m in agent.get_history()],
                    [("user", "写文章"), ("assistant", "初稿")],
                )

    def test_refines_latest_answer_until_iteration_limit(self):
        """每轮审查最新答案，达到上限后返回最后一次改进结果。"""
        agent, llm = self.make_agent(
            ["初稿", "补充例子", "第二稿", "补充总结", "最终稿"],
            max_iterations=2,
        )
        self.assertEqual(agent.run("写文章"), "最终稿")
        self.assertEqual(llm.invoke.call_count, 5)
        prompts = [call.args[0][-1]["content"] for call in llm.invoke.call_args_list]
        self.assertIn("初稿", prompts[2])
        self.assertIn("补充例子", prompts[2])
        self.assertIn("第二稿", prompts[3])
        self.assertIn("第二稿", prompts[4])
        self.assertIn("补充总结", prompts[4])
        self.assertEqual(agent.memory.get_last_execution(), "最终稿")

    def test_zero_iterations_only_generates_initial_answer(self):
        """零轮反思仍生成初稿，但不再调用评审或改进。"""
        agent, llm = self.make_agent(["初稿"], max_iterations=0)
        self.assertEqual(agent.run("写文章"), "初稿")
        self.assertEqual(llm.invoke.call_count, 1)

    def test_partial_custom_prompts_keep_independent_defaults(self):
        """部分覆盖不应丢失默认模板，也不能修改调用方的字典。"""
        custom_prompts = {"initial": "自定义任务:{task}"}
        agent, llm = self.make_agent(
            ["初稿", "无需改进"], custom_prompts=custom_prompts
        )
        self.assertEqual(agent.run("写文章"), "初稿")
        self.assertEqual(
            llm.invoke.call_args_list[0].args[0],
            [{"role": "user", "content": "自定义任务:写文章"}],
        )
        self.assertEqual(agent.prompts["reflect"], DEFAULT_PROMPTS["reflect"])
        agent.prompts["initial"] = "修改后的模板"
        other_agent, _ = self.make_agent([])
        self.assertEqual(other_agent.prompts, DEFAULT_PROMPTS)
        self.assertEqual(custom_prompts, {"initial": "自定义任务:{task}"})

    def test_custom_templates_receive_all_refinement_fields(self):
        """完整模板应能使用原任务、上一轮答案和反馈占位符。"""
        agent, llm = self.make_agent(
            ["初稿", "补充边界", "改进稿"],
            max_iterations=1,
            custom_prompts={
                "initial": "执行:{task}",
                "reflect": "审查:{task}|{content}",
                "refine": "改进:{task}|{last_attempt}|{feedback}",
            },
        )
        self.assertEqual(agent.run("编写函数"), "改进稿")
        self.assertEqual(
            [call.args[0][-1]["content"] for call in llm.invoke.call_args_list],
            ["执行:编写函数", "审查:编写函数|初稿", "改进:编写函数|初稿|补充边界"],
        )

    def test_system_prompt_and_options_reach_every_call(self):
        """各阶段都要传递系统提示词和模型调用参数。"""
        agent, llm = self.make_agent(
            ["初稿", "需要改进", "改进稿"],
            max_iterations=1,
            system_prompt="你是一位严谨的编辑。",
        )
        agent.run("写文章", temperature=0, max_tokens=64)
        for call in llm.invoke.call_args_list:
            self.assertEqual(
                call.args[0][0],
                {"role": "system", "content": "你是一位严谨的编辑。"},
            )
            self.assertEqual(call.kwargs, {"temperature": 0, "max_tokens": 64})

    def test_new_run_resets_working_memory_and_keeps_conversation_history(self):
        """不同任务的反思轨迹隔离，最终对话历史仍可连续查询。"""
        agent, _ = self.make_agent(
            ["第一份初稿", "无需改进", "第二份初稿", "无需改进"]
        )
        agent.run("任务一")
        agent.run("任务二")
        self.assertEqual(agent.memory.get_last_execution(), "第二份初稿")
        self.assertEqual(len(agent.memory.records), 2)
        self.assertEqual(len(agent.get_history()), 4)

    def test_invalid_iteration_limit_is_rejected(self):
        """无效的迭代次数应在调用模型之前被拒绝。"""
        for max_iterations in (-1, 1.5):
            with self.subTest(max_iterations=max_iterations):
                with self.assertRaisesRegex(ValueError, "非负整数"):
                    self.make_agent([], max_iterations=max_iterations)


